#nullable enable

using System;
using System.Collections.Generic;

namespace Trigger.Models;

public partial class PersonalAccessToken
{
    public string Id { get; set; } = null!;

    /// <summary>
    /// If generated by the CLI this will be "cli", otherwise user-provided
    /// </summary>
    public string Name { get; set; } = null!;

    /// <summary>
    /// This is the token encrypted using the ENCRYPTION_KEY
    /// </summary>
    public string EncryptedToken { get; set; } = null!;

    /// <summary>
    /// This is shown in the UI, with ********
    /// </summary>
    public string ObfuscatedToken { get; set; } = null!;

    /// <summary>
    /// This is used to find the token in the database
    /// </summary>
    public string HashedToken { get; set; } = null!;

    public virtual User User { get; set; } = null!;

    public string UserId { get; set; } = null!;

    public DateTime? RevokedAt { get; set; }

    public DateTime? LastAccessedAt { get; set; }

    /// <summary>
    /// After this the token no longer authenticates. Null means it never expires.
    /// </summary>
    public DateTime? ExpiresAt { get; set; }

    /// <summary>
    /// Set on CLI login tokens: they stop authenticating this many seconds after their last use
    /// (or creation, if never used). Null means no idle limit.
    /// </summary>
    public int? IdleTimeoutSeconds { get; set; }

    /// <summary>
    /// When the "about to expire" email was sent. Set before sending, so it's sent at most once.
    /// </summary>
    public DateTime? ExpiryReminderSentAt { get; set; }

    /// <summary>
    /// When the "has expired" email was sent. Set before sending, so it's sent at most once.
    /// </summary>
    public DateTime? ExpiredNoticeSentAt { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    public virtual ICollection<AuthorizationCode> AuthorizationCodes { get; set; } = new List<AuthorizationCode>();

    public virtual OAuthClient? OauthClient { get; set; }

    public string? OauthClientId { get; set; }

    public virtual ICollection<OAuthRefreshToken> OauthRefreshTokens { get; set; } = new List<OAuthRefreshToken>();
}
